def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    def mk(n, k):
        return [0] * k + [1] * (n - k)
    tests = [fmt([0]), fmt([1]), fmt([0, 1]), fmt([0, 0]), fmt([1, 1]),
             fmt(mk(10, 0)), fmt(mk(10, 10)), fmt(mk(10, 9)), fmt(mk(10, 1))]
    for n in (3, 5, 8, 12, 20, 40, 60):
        for _ in range(2):
            tests.append(fmt(mk(n, rng.randint(0, n))))
    N = 10**6
    tests.append(fmt(mk(N, rng.randint(1, N - 1))))
    tests.append(fmt(mk(N, N - 1)))
    tests.append(fmt(mk(N, N)))
    return tests
